package com.yeeyuan;
import java.util.*;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;
@Component
public class Bootstrap implements ApplicationRunner {
 final Db db;final Auth auth;final Settings config;final Crypto crypto;
 public Bootstrap(Db db,Auth auth,Settings config,Crypto crypto){this.db=db;this.auth=auth;this.config=config;this.crypto=crypto;}
 @Override @Transactional public void run(ApplicationArguments args){UUID store=(UUID)db.one("SELECT id FROM store LIMIT 1").get("id");if(config.local())db.jdbc.update("UPDATE store SET accepting_orders=true");String username=config.adminUsername()==null||config.adminUsername().isBlank()?"owner":config.adminUsername().trim();String role=config.adminRole()==null||config.adminRole().isBlank()?"OWNER":config.adminRole().trim().toUpperCase(Locale.ROOT);if(!Set.of("OWNER","MANAGER","CASHIER","KITCHEN").contains(role))throw new IllegalArgumentException("Bootstrap staff role is invalid");if(!config.adminPassword().isBlank()){if(config.adminPassword().length()<12)throw new IllegalArgumentException("Bootstrap password must have at least 12 characters");String displayName=username.equals("owner")?"เจ้าของร้าน":username;String mfa=config.adminTotpSecret().isBlank()&&config.local()?"LOCAL_MFA_DISABLED":crypto.encrypt(config.adminTotpSecret());var found=db.jdbc.queryForList("SELECT id FROM app_user WHERE username=?",username);UUID id;if(found.isEmpty()){id=UUID.randomUUID();db.jdbc.update("INSERT INTO app_user(id,kind,username,display_name,password_hash,totp_secret_ciphertext) VALUES(?,'STAFF',?,?,?,?)",id,username,displayName,auth.encodePassword(config.adminPassword()),mfa);}else{id=UUID.fromString(String.valueOf(found.get(0).get("id")));db.jdbc.update("UPDATE app_user SET kind='STAFF',display_name=?,password_hash=?,totp_secret_ciphertext=?,active=true WHERE id=?",displayName,auth.encodePassword(config.adminPassword()),mfa,id);db.jdbc.update("DELETE FROM staff_role WHERE user_id=?",id);}db.jdbc.update("INSERT INTO staff_role(user_id,store_id,role) VALUES(?,?,?)",id,store,role);}for(int n=1;n<=5;n++)db.jdbc.update("INSERT INTO dining_table(store_id,code,qr_token_hash) VALUES(?,?,?) ON CONFLICT(store_id,code) DO NOTHING",store,String.format("%02d",n),Crypto.hash(Crypto.token()));}
}
